using System.Text;using System.Text.Json;using Dip.Application.Abstractions.GitHub;using Dip.Application.Features.GitHub;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.RateLimiting;
namespace Dip.Api.Controllers;
[ApiController][Route("api/v1/webhooks/github")][AllowAnonymous][EnableRateLimiting("github-webhook")][Consumes("application/json")]
public sealed class WebhooksController(IGitHubWebhookVerifier verifier,GitHubWebhookProcessor processor):ControllerBase
{
 const int Max=5*1024*1024;static readonly HashSet<string> Supported=new(StringComparer.OrdinalIgnoreCase){"ping","push","pull_request","check_run","workflow_run"};
 [HttpPost][RequestSizeLimit(Max)]public async Task<IActionResult> Receive(CancellationToken ct){var signature=Request.Headers["X-Hub-Signature-256"].FirstOrDefault();var delivery=Request.Headers["X-GitHub-Delivery"].FirstOrDefault();var evt=Request.Headers["X-GitHub-Event"].FirstOrDefault();if(string.IsNullOrWhiteSpace(signature)||string.IsNullOrWhiteSpace(delivery)||string.IsNullOrWhiteSpace(evt))return BadRequest();await using var ms=new MemoryStream();await Request.Body.CopyToAsync(ms,ct);if(ms.Length==0||ms.Length>Max)return BadRequest();var bytes=ms.ToArray();if(!verifier.Verify(bytes,signature))return Unauthorized();var text=Encoding.UTF8.GetString(bytes);try{using var _=JsonDocument.Parse(text);}catch(JsonException){return BadRequest();}if(evt.Equals("ping",StringComparison.OrdinalIgnoreCase))return Ok(new{deliveryId=delivery,eventName=evt,accepted=true});if(!Supported.Contains(evt))return Accepted(new{deliveryId=delivery,eventName=evt,ignored=true});var result=await processor.ProcessAsync(delivery,evt,text,ct);return result.WasDuplicate?Ok(result):Accepted(result);}
}
